"use client";
import {
  Select,
  Button,
  Label,
  SelectValue,
  Popover,
  ListBox,
  ListBoxItem,
} from "react-aria-components";
import {
  ControlRoll,
  ControlStyles,
  controlVariables,
  useControlValue,
  type ControlAppearance,
} from "./control-shared";
export interface MorphingSelectItem {
  id: string;
  label: string;
  disabled?: boolean;
}
export interface MorphingSelectProps extends ControlAppearance {
  items: readonly MorphingSelectItem[];
  value?: string | null;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  label?: string;
  hideLabel?: boolean;
  placeholder?: string;
  name?: string;
  disabled?: boolean;
  required?: boolean;
  gap?: number;
}
export function MorphingSelect({
  items,
  value,
  defaultValue,
  onValueChange,
  open,
  defaultOpen = false,
  onOpenChange,
  label = "Discipline",
  hideLabel = false,
  placeholder = "Select an option",
  name,
  disabled = false,
  required = false,
  gap = 12,
  ...appearance
}: MorphingSelectProps) {
  const [isOpen, setOpen] = useControlValue(open, defaultOpen, onOpenChange);
  const variables = controlVariables(appearance);
  return (
    <>
      <ControlStyles />
      <Select
        className={`z-mc z-mc-select ${appearance.className ?? ""}`}
        style={variables}
        aria-label={hideLabel ? label : undefined}
        selectedKey={value}
        defaultSelectedKey={defaultValue}
        onSelectionChange={(key) => {
          if (key != null) onValueChange?.(String(key));
        }}
        isOpen={isOpen}
        onOpenChange={setOpen}
        placeholder={placeholder}
        name={name}
        isDisabled={disabled}
        isRequired={required}
        disabledKeys={items.filter((i) => i.disabled).map((i) => i.id)}
      >
        {!hideLabel && <Label className="z-mc-select-label">{label}</Label>}
        <Button className="z-mc-pill z-mc-select-trigger">
          <SelectValue>
            {({ selectedText }) => (
              <ControlRoll id={selectedText || placeholder} duration={appearance.duration}>
                {selectedText || placeholder}
              </ControlRoll>
            )}
          </SelectValue>
          <span aria-hidden="true" className="z-mc-select-chevron">
            ⌄
          </span>
        </Button>
        <Popover
          className="z-mc z-mc-select-popover"
          style={variables}
          offset={gap}
          placement="bottom start"
        >
          <span className="z-mc-neck" aria-hidden="true" />
          <ListBox className="z-mc-select-list" items={items}>
            {(item) => (
              <ListBoxItem id={item.id} textValue={item.label} className="z-mc-option">
                {item.label}
              </ListBoxItem>
            )}
          </ListBox>
        </Popover>
      </Select>
    </>
  );
}
